CREATE TABLE signal_expert_grants(id uuid PRIMARY KEY,user_id integer NOT NULL REFERENCES signal_users(id),granted_by text NOT NULL,authority text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE signal_assessment_appeals(id uuid PRIMARY KEY,user_id integer NOT NULL REFERENCES signal_users(id),kind text NOT NULL CHECK(kind IN ('skill','legacy')),attempt_id integer NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_review','resolved')),revision integer NOT NULL DEFAULT 1,cycle integer NOT NULL DEFAULT 1,grounds_hashes text[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,attempt_id));
CREATE TABLE signal_appeal_messages(id uuid PRIMARY KEY,appeal_id uuid NOT NULL REFERENCES signal_assessment_appeals(id),author_id integer NOT NULL REFERENCES signal_users(id),authority_id uuid REFERENCES signal_expert_grants(id),visibility text NOT NULL CHECK(visibility IN ('candidate','internal')),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE signal_assessment_heads(id text PRIMARY KEY,user_id integer NOT NULL REFERENCES signal_users(id),kind text NOT NULL CHECK(kind IN ('skill','legacy')),attempt_id integer NOT NULL,revision integer NOT NULL DEFAULT 1,decision_id uuid,validity text NOT NULL DEFAULT 'original' CHECK(validity IN ('original','valid','invalid')),decision jsonb,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE signal_assessment_review_decisions(id uuid PRIMARY KEY,appeal_id uuid NOT NULL REFERENCES signal_assessment_appeals(id),actor_id integer NOT NULL REFERENCES signal_users(id),authority_id uuid NOT NULL REFERENCES signal_expert_grants(id),authority text NOT NULL,command_key uuid NOT NULL UNIQUE,payload_hash text NOT NULL,supersedes uuid REFERENCES signal_assessment_review_decisions(id),previous_revision integer NOT NULL,revision integer NOT NULL,action text NOT NULL CHECK(action IN ('confirm','correct','invalidate','new_check')),explanation text NOT NULL,internal_note text NOT NULL,source jsonb NOT NULL,affected_skills text[] NOT NULL,case_reviews jsonb NOT NULL,projection jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE signal_qualification_projection_events(id uuid PRIMARY KEY,user_id integer NOT NULL REFERENCES signal_users(id),decision_id uuid NOT NULL UNIQUE REFERENCES signal_assessment_review_decisions(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER signal_review_decisions_immutable BEFORE UPDATE OR DELETE ON signal_assessment_review_decisions FOR EACH ROW EXECUTE FUNCTION signal_invitation_history_immutable();
CREATE TRIGGER signal_appeal_messages_immutable BEFORE UPDATE OR DELETE ON signal_appeal_messages FOR EACH ROW EXECUTE FUNCTION signal_invitation_history_immutable();
CREATE TRIGGER signal_projection_event_immutable BEFORE UPDATE OR DELETE ON signal_qualification_projection_events FOR EACH ROW EXECUTE FUNCTION signal_invitation_history_immutable();
CREATE TRIGGER signal_professional_epoch AFTER INSERT OR UPDATE OR DELETE ON signal_assessment_heads FOR EACH STATEMENT EXECUTE FUNCTION signal_bump_professional_epoch();
CREATE INDEX signal_appeal_owner_idx ON signal_assessment_appeals(user_id,updated_at);
